def halvings(n):
    steps = 0
    while n > 1:
        n = n // 2      # throw away half
        steps += 1
    return steps

for n in (8, 1024, 1000000):
    print("n =", n, "-> halving steps:", halvings(n))

def is_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

for s in ["(a + b) * [c]", "{[()]}", "(]", "((a)"]:
    print(repr(s), "->", is_balanced(s))

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def prepend(self, value):          # add at the front, O(1)
        node = Node(value)
        node.next = self.head
        self.head = node

    def append(self, value):           # add at the end, O(n)
        node = Node(value)
        if self.head is None:
            self.head = node
            return
        cur = self.head
        while cur.next is not None:
            cur = cur.next
        cur.next = node

    def delete(self, value):           # remove first match, O(n)
        if self.head is None:
            return
        if self.head.value == value:
            self.head = self.head.next
            return
        cur = self.head
        while cur.next is not None:
            if cur.next.value == value:
                cur.next = cur.next.next   # skip the node
                return
            cur = cur.next

    def to_list(self):                 # walk and collect, O(n)
        items = []
        cur = self.head
        while cur is not None:
            items.append(cur.value)
            cur = cur.next
        return items

