def inorder(root, out):
    if root is not None:
        inorder(root.left, out)     # 1. left
        out.append(root.key)        # 2. node
        inorder(root.right, out)    # 3. right
    return out

def height(root):
    if root is None:
        return -1                   # empty tree
    return 1 + max(height(root.left), height(root.right))

