def simple_hash(key, size):
    return sum(ord(ch) for ch in key) % size

class HashTable:
    def __init__(self, size=5):
        self.size = size
        self.buckets = [[] for _ in range(size)]

    def put(self, key, value):
        bucket = self.buckets[simple_hash(key, self.size)]
        for pair in bucket:
            if pair[0] == key:
                pair[1] = value        # update existing key
                return
        bucket.append([key, value])    # new key (chaining)

    def get(self, key):
        bucket = self.buckets[simple_hash(key, self.size)]
        for k, v in bucket:
            if k == key:
                return v
        return None

