from collections import deque

graph = {
    "A": ["B", "C"], "B": ["A", "D", "E"], "C": ["A", "F"],
    "D": ["B"], "E": ["B", "F"], "F": ["C", "E"],
}

def bfs(graph, start):
    visited = {start}
    queue = deque([start])
    order = []
    while queue:
        v = queue.popleft()          # take from the front
        order.append(v)
        for nb in graph[v]:
            if nb not in visited:
                visited.add(nb)      # mark when we add to the queue
                queue.append(nb)
    return order

print("BFS from A:", bfs(graph, "A"))

graph = {
    "A": ["B", "C"], "B": ["A", "D", "E"], "C": ["A", "F"],
    "D": ["B"], "E": ["B", "F"], "F": ["C", "E"],
}

def dfs(graph, v, visited=None):
    if visited is None:
        visited = []
    visited.append(v)
    for nb in graph[v]:
        if nb not in visited:
            dfs(graph, nb, visited)  # go deeper first
    return visited

print("DFS from A:", dfs(graph, "A"))
